#include "stdlib/blas/ext/base/ndarray/slogspace.h"
#include "stdlib/blas/ext/base/slogspace.h"
#include "stdlib/ndarray/ctor.h"
#include "stdlib/blas/base/shared.h"
#include <stdbool.h>

/**
* Fills a one-dimensional single-precision floating-point ndarray with logarithmically spaced values over a specified interval.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a zero-dimensional ndarray specifying the base of the logarithmic scale.
*     -   a zero-dimensional ndarray specifying the exponent of the starting value.
*     -   a zero-dimensional ndarray specifying the exponent of the final value.
*     -   a zero-dimensional ndarray specifying whether to include the `base^stop` value when writing values to the input ndarray.
*
* @param arrays    list containing ndarrays
*/
void stdlib_blas_ext_slogspace( const struct ndarray *arrays[] ) {
	const struct ndarray *x = arrays[ 0 ];

	float base;
	float strt;
	float stp;
	bool endpoint;

	const CBLAS_INT N = stdlib_ndarray_dimension( x, 0 );
	const CBLAS_INT strideX = stdlib_ndarray_stride_elements( x, 0 );
	const CBLAS_INT offsetX = stdlib_ndarray_offset_elements( x );

	float *dataX = (float *)stdlib_ndarray_data( x );

	stdlib_ndarray_get_float32( arrays[ 1 ], NULL, &base );
	stdlib_ndarray_get_float32( arrays[ 2 ], NULL, &strt );
	stdlib_ndarray_get_float32( arrays[ 3 ], NULL, &stp );
	stdlib_ndarray_get_bool( arrays[ 4 ], NULL, &endpoint );
	
 	API_SUFFIX(stdlib_strided_slogspace_ndarray)( N, base, strt, stp, endpoint, dataX, strideX, offsetX );
}